def semver_sort(versions):
    def parse_version(version):
        # Split off build metadata (everything after '+')
        if '+' in version:
            version_part, build = version.split('+', 1)
        else:
            version_part = version

        # Split off pre-release (everything after '-')
        if '-' in version_part:
            core_part, prerelease = version_part.split('-', 1)
        else:
            core_part = version_part
            prerelease = None

        # Parse MAJOR.MINOR.PATCH
        parts = core_part.split('.')
        major = int(parts[0])
        minor = int(parts[1])
        patch = int(parts[2])

        # Parse pre-release identifiers
        if prerelease:
            prerelease_identifiers = prerelease.split('.')
            prerelease_parsed = []
            for identifier in prerelease_identifiers:
                if identifier.isdigit():
                    prerelease_parsed.append((0, int(identifier)))
                else:
                    prerelease_parsed.append((1, identifier))
        else:
            prerelease_parsed = None

        return (major, minor, patch, prerelease_parsed)

    def sort_key(version):
        major, minor, patch, prerelease_parsed = parse_version(version)

        # Build sort key tuple
        # For pre-release: if None, sort after (use a tuple that sorts after any list)
        # If not None, sort before
        if prerelease_parsed is None:
            prerelease_key = (1,)  # Sorts after pre-release versions
        else:
            prerelease_key = (0, tuple(prerelease_parsed))  # Sorts before

        return (major, minor, patch, prerelease_key)

    # Use stable sort to maintain input order for equal precedence
    return sorted(versions, key=sort_key)

